-- Heritage places researched by Aksh (Udaipur and Kolkata "Heritage Master" workbooks, 2026-10-15/16):
-- 20 Udaipur and 305 Kolkata places, each with a map position where the workbook has one.
-- Like facts, every place arrives as 'needs_check' and stays hidden from the website until a teammate checks
-- its source on the editor page (Places tab) and presses Verify. created_by is NULL, meaning "imported".
-- The workbook's own research notes are kept: research_status and confidence are Aksh's labels, and
-- details holds every other filled-in column of the row, under the workbook's column names.
-- source_url starts as the place's Wikipedia page, else its Wikidata page, else empty (add one before verifying).

CREATE TABLE heritage_places (
  id              SERIAL PRIMARY KEY,
  city_id         TEXT NOT NULL REFERENCES cities(id) ON DELETE CASCADE,
  code            TEXT UNIQUE,                         -- the workbook's Entity_ID, e.g. KOL-BLT-0001
  name            TEXT NOT NULL,
  native_name     TEXT NOT NULL DEFAULT '',            -- Hindi for Udaipur, Bengali for Kolkata
  aliases         JSONB NOT NULL DEFAULT '[]',
  category        TEXT NOT NULL DEFAULT '',            -- Entity_Level1, e.g. Built Architecture & Fortifications
  subcategory     TEXT NOT NULL DEFAULT '',            -- Entity_Level2, e.g. Lakes (Jheel)
  subtype         TEXT NOT NULL DEFAULT '',
  description     TEXT NOT NULL DEFAULT '',
  significance    TEXT NOT NULL DEFAULT '',
  latitude        DOUBLE PRECISION,
  longitude       DOUBLE PRECISION,
  coord_method    TEXT NOT NULL DEFAULT '',            -- how the position was found, e.g. 'Manual approx (+-300 m)'
  year            INTEGER,                             -- estimated year it began
  year_basis      TEXT NOT NULL DEFAULT '',
  epoch           TEXT NOT NULL DEFAULT '',
  style           TEXT NOT NULL DEFAULT '',
  wikidata_qid    TEXT NOT NULL DEFAULT '',
  wikipedia_url   TEXT NOT NULL DEFAULT '',
  image_url       TEXT NOT NULL DEFAULT '',
  image_license   TEXT NOT NULL DEFAULT '',
  source_url      TEXT NOT NULL DEFAULT '',
  source_ids      TEXT NOT NULL DEFAULT '',            -- the workbook's source register ids, e.g. S07;S26
  source_type     TEXT NOT NULL DEFAULT '',            -- e.g. Wikidata, Seed (manual)
  research_status TEXT NOT NULL DEFAULT '',            -- Aksh's Verification_Status, e.g. Cross-checked (2+ sources)
  confidence      TEXT NOT NULL DEFAULT '',            -- High / Medium / Low
  details         JSONB NOT NULL DEFAULT '{}',
  status          TEXT NOT NULL DEFAULT 'needs_check' CHECK (status IN ('needs_check', 'verified')),
  sort_order      INTEGER NOT NULL DEFAULT 0,
  created_by      INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by      INTEGER REFERENCES users(id) ON DELETE SET NULL,
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  verified_by     INTEGER REFERENCES users(id) ON DELETE SET NULL,
  verified_at     TIMESTAMPTZ
);
CREATE INDEX heritage_places_city ON heritage_places (city_id);

